"""Join a list of items into one text.

Without `item_template`, every item must be a string, and the items are
joined with `separator`, two line breaks unless the step gives another.

With `item_template`, every item must be an object, and each is first
rendered through the template from its own fields. The template uses the
same placeholders as prompt templates: `{name}` is replaced by the item's
field `name`, and `{{` and `}}` are literal braces. A string is inserted as
it is, and any other value as compact JSON. Only plain names are allowed.
"""

import json
import string
import sys

TOOL = "join_text"
INPUTS = ("items", "separator", "item_template")
DEFAULT_SEPARATOR = "\n\n"
TYPE_NAMES = (
    (dict, "an object"),
    (list, "an array"),
    (str, "a string"),
    (bool, "a boolean"),
    (int, "a number"),
    (float, "a number"),
)


def fail(status, message):
    sys.stderr.write(message)
    sys.exit(status)


def read_inputs():
    inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

    for name in inputs:
        if name not in INPUTS:
            fail(2, f"{TOOL} does not take the input {name!r}.")

    if "items" not in inputs:
        fail(2, f"{TOOL} needs the input 'items'.")

    return inputs


def type_name(value):
    for kind, name in TYPE_NAMES:
        if isinstance(value, kind):
            return name

    return "null"


def parse(template):
    try:
        pieces = list(string.Formatter().parse(template))
    except ValueError as error:
        fail(2, f"{TOOL} could not read the item template: {error}.")

    for _, name, spec, conversion in pieces:
        if name is None:
            continue

        if not name.isidentifier() or spec or conversion is not None:
            shown = "{" + name + ("!" + conversion if conversion else "")
            shown = shown + (":" + spec if spec else "") + "}"
            fail(2, f"{TOOL} allows only plain {{name}} placeholders; {shown} is not one.")

    return pieces


def render_value(value):
    if isinstance(value, str):
        return value

    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def render(pieces, item, index):
    parts = []

    for literal, name, _, _ in pieces:
        parts.append(literal)

        if name is None:
            continue

        if name not in item:
            fail(1, f"{TOOL} found no value for {{{name}}} in item $[{index}].")

        parts.append(render_value(item[name]))

    return "".join(parts)


inputs = read_inputs()
items = inputs["items"]
separator = inputs.get("separator", DEFAULT_SEPARATOR)
templated = "item_template" in inputs

if not isinstance(items, list):
    fail(2, f"{TOOL} needs 'items' to be an array.")

if not isinstance(separator, str):
    fail(2, f"{TOOL} needs 'separator' to be a string.")

if not templated:
    for index, item in enumerate(items):
        if not isinstance(item, str):
            fail(
                2,
                f"{TOOL} joins strings, or objects through an item_template; "
                f"item $[{index}] is {type_name(item)}.",
            )

    texts = items
else:
    template = inputs["item_template"]

    if not isinstance(template, str):
        fail(2, f"{TOOL} needs 'item_template' to be a string.")

    pieces = parse(template)
    texts = []

    for index, item in enumerate(items):
        if not isinstance(item, dict):
            fail(
                2,
                f"{TOOL} fills its item_template from objects; "
                f"item $[{index}] is {type_name(item)}.",
            )

        texts.append(render(pieces, item, index))

result = separator.join(texts)

sys.stdout.buffer.write(json.dumps({"text": result}, ensure_ascii=False).encode("utf-8"))
